import{_ as a,o as t,c as i,a2 as e}from"./chunks/framework.Bqa2y7hU.js";const c=JSON.parse('{"title":"回调地址与公网域名","description":"什么时候需要公网域名、怎么配 webhook_domain，以及 8080 与 8081 两个端口的区别。","frontmatter":{"title":"回调地址与公网域名","description":"什么时候需要公网域名、怎么配 webhook_domain，以及 8080 与 8081 两个端口的区别。"},"headers":[],"relativePath":"platforms/callback.md","filePath":"platforms/callback.md","lastUpdated":1789487229000}'),o={name:"platforms/callback.md"};function n(l,s,h,d,r,p){return t(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="回调地址与公网域名-🌍" tabindex="-1">回调地址与公网域名 🌍 <a class="header-anchor" href="#回调地址与公网域名-🌍" aria-label="Permalink to &quot;回调地址与公网域名 🌍&quot;">​</a></h1><p>这页解决两个问题：<strong>什么时候必须准备公网域名</strong>，以及<strong>端口该怎么放行</strong>。这两件事配错了，表现都是「机器人配置没问题，但就是收不到消息」。</p><p>如果你用的是 WebSocket 网关接入 QQ 官方，或者用 OneBot 11 反向 WebSocket，这页里只有「端口放行」一节和你有关；公网域名部分可以跳过。</p><h2 id="_1-什么时候需要公网域名" tabindex="-1">1. 什么时候需要公网域名 <a class="header-anchor" href="#_1-什么时候需要公网域名" aria-label="Permalink to &quot;1. 什么时候需要公网域名&quot;">​</a></h2><p>只有当<strong>平台要主动连你</strong>的时候才需要公网域名：</p><table tabindex="0"><thead><tr><th>接入方式</th><th>谁发起连接</th><th>需要公网域名吗</th></tr></thead><tbody><tr><td>QQ 官方：WebSocket 网关</td><td>框架连平台</td><td>不需要</td></tr><tr><td>QQ 官方：Webhook 回调</td><td>平台回调你</td><td><strong>需要</strong></td></tr><tr><td>QQ OneBot 11：反向 WebSocket</td><td>实现端连框架</td><td>不需要</td></tr></tbody></table><p>Webhook 模式下，QQ 开放平台会把事件 POST 到你给的回调地址，所以那个地址必须是公网上能解析、能访问、证书有效的地址。内网地址、<code>localhost</code>、只在你本机能解析的域名都不行。</p><h2 id="_2-回调地址是怎么拼出来的" tabindex="-1">2. 回调地址是怎么拼出来的 <a class="header-anchor" href="#_2-回调地址是怎么拼出来的" aria-label="Permalink to &quot;2. 回调地址是怎么拼出来的&quot;">​</a></h2><p>回调地址形如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{协议}://{域名}/api/webhooks/adapters/qq_official/{机器人UUID}</span></span></code></pre></div><p><code>{协议}</code> 和 <code>{域名}</code> 不是手填的，来自「平台设置 → 站点」里的两个配置项：</p><table tabindex="0"><thead><tr><th>配置项</th><th>作用</th><th>建议值</th></tr></thead><tbody><tr><td><code>webhook_protocol</code></td><td>决定回调地址用 <code>http</code> 还是 <code>https</code></td><td><code>https</code></td></tr><tr><td><code>webhook_domain</code></td><td>决定回调地址用哪个域名</td><td>你的公网域名，例如 <code>example.com</code></td></tr></tbody></table><p>配好这两个值之后，再去控制台创建 / 查看 Webhook 模式的机器人，弹出的回调地址就是固定的了。</p><div class="danger custom-block"><p class="custom-block-title">没配 <code>webhook_domain</code> 会退化成当前 Host</p><p>这是最容易踩的坑：<code>webhook_domain</code> 为空时，回调地址会<strong>退化成你当前浏览器访问控制台所用的 Host</strong>。</p><p>后果是——你在公司电脑上看到的是 <code>http://&lt;内网地址&gt;:8080/...</code>，在另一台机器上看到的是另一个地址，填到 QQ 开放平台的那一个，平台根本回调不到。<strong>务必先配 <code>webhook_domain</code>，再复制回调地址。</strong></p></div><h2 id="_3-配好域名之后要做的事" tabindex="-1">3. 配好域名之后要做的事 <a class="header-anchor" href="#_3-配好域名之后要做的事" aria-label="Permalink to &quot;3. 配好域名之后要做的事&quot;">​</a></h2><p>一个能用的公网入口，通常包括这几步：</p><ol><li>把域名解析到你的服务器</li><li>反向代理（reverse proxy）把外部请求转发到框架的管理面端口</li><li>申请证书、开启 HTTPS，并把 <code>webhook_protocol</code> 设成 <code>https</code></li><li>反向代理<strong>必须透传 <code>Host</code> 头</strong></li></ol><p>第 4 条单独强调一下。如果代理不转发 <code>Host</code>，框架看到的主机名就是代理自己的地址，凡是用到主机名判断的逻辑都会失准。</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Nginx：站点入口转发到管理面（8080），并透传 Host</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssl;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://&lt;你的服务器IP&gt;:8080;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 框架与代理同机时填回环地址</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 必须：透传原始 Host</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Real-IP $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-Proto $scheme;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>完整的反代与 HTTPS 步骤见 <a href="/RuaBot.Doc/deploy/reverse-proxy">反向代理与 HTTPS</a>。</p><h2 id="_4-端口-8080-和-8081-不是一回事" tabindex="-1">4. 端口：8080 和 8081 不是一回事 <a class="header-anchor" href="#_4-端口-8080-和-8081-不是一回事" aria-label="Permalink to &quot;4. 端口：8080 和 8081 不是一回事&quot;">​</a></h2><p>这是第二个高频坑。两个端口都监听着，但服务的东西完全不同：</p><table tabindex="0"><thead><tr><th>端口</th><th>用途</th><th>谁连它</th></tr></thead><tbody><tr><td><code>8080</code></td><td>管理面：控制台页面、开放 API、Webhook 回调</td><td>你的浏览器、QQ 开放平台</td></tr><tr><td><code>8081</code></td><td>适配器数据面：OneBot 反向 WebSocket</td><td>NapCat / Lagrange / go-cqhttp 等实现端</td></tr></tbody></table><p>由此推出两条实践建议：</p><ul><li><strong>对外只需要暴露 8080</strong>（通常再套一层反向代理和 HTTPS）。控制台、回调、开放 API 都走这里。</li><li><strong>8081 不用对外开放</strong>。它是 OneBot 实现端连进来的入口。如果实现端和框架不在同一台机器上，才需要放行 8081，并且最好限制来源。</li><li>在防火墙 / 安全组里，别把 8081 当成「另一个 8080」对外放开。</li></ul><h2 id="_5-排查清单" tabindex="-1">5. 排查清单 <a class="header-anchor" href="#_5-排查清单" aria-label="Permalink to &quot;5. 排查清单&quot;">​</a></h2><h3 id="症状-浏览器打不开控制台-但服务明明是启动的" tabindex="-1">症状：浏览器打不开控制台，但服务明明是启动的 <a class="header-anchor" href="#症状-浏览器打不开控制台-但服务明明是启动的" aria-label="Permalink to &quot;症状：浏览器打不开控制台，但服务明明是启动的&quot;">​</a></h3><ul><li><strong>原因</strong>：只放行了 8081，或反向代理指向了 8081。</li><li><strong>处理方式</strong>：确认代理的 <code>proxy_pass</code> 指向 <strong>8080</strong>。用下面命令确认 8080 在监听。</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux：确认两个端口的监听情况</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lntp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;8080|8081&#39;</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows：确认两个端口的监听情况</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-NetTCPConnection</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LocalPort </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8081</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">State Listen</span></span></code></pre></div><h3 id="症状-控制台能开-但-onebot-机器人一直离线" tabindex="-1">症状：控制台能开，但 OneBot 机器人一直离线 <a class="header-anchor" href="#症状-控制台能开-但-onebot-机器人一直离线" aria-label="Permalink to &quot;症状：控制台能开，但 OneBot 机器人一直离线&quot;">​</a></h3><ul><li><strong>原因</strong>：只放行了 8080，实现端连不上 8081。</li><li><strong>处理方式</strong>：按第 4 节确认实现端填的端口是 <strong>8081</strong>，并确认该端口对实现端可达。</li></ul><h3 id="症状-webhook-模式下平台上校验回调失败" tabindex="-1">症状：Webhook 模式下平台上校验回调失败 <a class="header-anchor" href="#症状-webhook-模式下平台上校验回调失败" aria-label="Permalink to &quot;症状：Webhook 模式下平台上校验回调失败&quot;">​</a></h3><ul><li><strong>原因</strong>：<code>webhook_domain</code> 没配，回调地址退化成了内网 Host。</li><li><strong>处理方式</strong>：配好 <code>webhook_domain</code> 与 <code>webhook_protocol</code>，重新复制回调地址并回填 QQ 开放平台。</li></ul><h3 id="症状-回调通了-但事件里的来源信息不对" tabindex="-1">症状：回调通了，但事件里的来源信息不对 <a class="header-anchor" href="#症状-回调通了-但事件里的来源信息不对" aria-label="Permalink to &quot;症状：回调通了，但事件里的来源信息不对&quot;">​</a></h3><ul><li><strong>原因</strong>：反向代理没有透传 <code>Host</code>。</li><li><strong>处理方式</strong>：在代理配置里补上 <code>proxy_set_header Host $host;</code> 并重载。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/platforms/qq-official-webhook">QQ 官方：Webhook 回调</a></li><li><a href="/RuaBot.Doc/deploy/reverse-proxy">反向代理与 HTTPS</a></li><li><a href="/RuaBot.Doc/platforms/qq-onebot">QQ OneBot 11</a></li></ul>`,38)])])}const g=a(o,[["render",n]]);export{c as __pageData,g as default};
